DROP TABLE IF EXISTS `bak_lepgs_splms_lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `bak_lepgs_splms_lessons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `alias` varchar(255) NOT NULL DEFAULT '',
  `description` text DEFAULT NULL,
  `short_description` varchar(255) DEFAULT '',
  `course_id` bigint(20) unsigned NOT NULL,
  `teacher_id` int(11) NOT NULL,
  `topic_id` int(11) DEFAULT NULL,
  `video_url` varchar(255) DEFAULT '',
  `vdo_thumb` text NOT NULL,
  `ordering` int(11) NOT NULL DEFAULT 0,
  `video_duration` varchar(50) DEFAULT '',
  `attachment` varchar(255) DEFAULT '',
  `lesson_type` tinyint(1) NOT NULL DEFAULT 1,
  `published` tinyint(1) NOT NULL DEFAULT 1,
  `access` int(11) NOT NULL DEFAULT 1,
  `language` char(7) NOT NULL DEFAULT '*',
  `created_by` bigint(20) NOT NULL DEFAULT 0,
  `created` datetime NOT NULL,
  `modified_by` bigint(20) NOT NULL DEFAULT 0,
  `modified` datetime NOT NULL,
  `checked_out` bigint(20) NOT NULL DEFAULT 0,
  `checked_out_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

